#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, k, a, b;
    cin >> n >> k >> a >> b;

    __int128 result = 0;

    if (k <= 1) {
        result = (__int128)(n - 1) * a;
    } else {
        while (n > 1) {
            if (n < k) {
                result += (__int128)(n - 1) * a;
                break;
            }

            long long remainder = n % k;
            if (remainder != 0) {
                result += (__int128)remainder * a;
                n -= remainder;
            } else {
                long long next = n / k;
                result += min((__int128)b, (__int128)(n - next) * a);
                n = next;
            }
        }
    }

    if (result == 0) {
        cout << 0;
    } else {
        string answer;
        while (result > 0) {
            answer.push_back(char('0' + result % 10));
            result /= 10;
        }
        reverse(answer.begin(), answer.end());
        cout << answer;
    }

    return 0;
}

